'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`u${Date.now()}${Math.random().toString(36).slice(2)}`;
const defaults=()=>({version:1,own:[],notes:{},materials:{},relations:[],bounds:[476,1492,1789,1914],boundaryReason:'',boundaryHistory:[],lensAssignments:{},interpretations:{}});
let state=defaults(),db,assets={},onlyOwn=false,selected=null,assetReady=false,currentId=null,saveChain=Promise.resolve(),toastTimer;
const popup=$('#popup'),body=$('#dialogBody');
const all=()=>[...EVENTS,...state.own];
const byId=id=>all().find(e=>e.id===id)||CONCEPTS[id];
const yr=y=>y<0?`${Math.abs(y).toLocaleString('de-CH')} v. u. Z.`:String(Math.round(y));
const astronomical=y=>y<0?y+1:y;
const yearDiff=(a,b)=>Math.abs(astronomical(b)-astronomical(a));
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
async function init(){
 try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('zeitspuren-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const saved=await new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(saved)state=validate(saved);$('#storageStatus').textContent='Auf diesem Gerät gespeichert · mit Export übertragbar';}
 catch(e){$('#storageStatus').textContent='Lokales Speichern nicht verfügbar – Arbeitsstand unbedingt exportieren.';toast('Speicher nicht verfügbar. Export bleibt möglich.');}
 assets=Object.fromEntries(IMAGE_MANIFEST.map(a=>[a.filename,a]));assetReady=true;
 renderVisualRibbon();render();
}
function save(){captureReadings();const snap=JSON.parse(JSON.stringify(state));if(!db)return Promise.resolve(false);$('#storageStatus').textContent='Wird gespeichert …';saveChain=saveChain.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(snap,'state');tx.oncomplete=()=>{$('#storageStatus').textContent='Auf diesem Gerät gespeichert · mit Export übertragbar';resolve(true)};tx.onerror=()=>{$('#storageStatus').textContent='Speichern fehlgeschlagen – bitte exportieren.';toast('Speicher voll oder nicht verfügbar. Bitte exportieren.');reject(tx.error)}}));return saveChain.catch(()=>false)}
function show(html,kicker='SPUR UNTERSUCHEN'){stopHistoricalMedia();body.innerHTML=html;$('#dialogKicker').textContent=kicker;if(!popup.open)popup.showModal();popup.scrollTop=0;bindOpen();}
function bindOpen(){body.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openEvent(b.dataset.open));}
function sourceHtml(keys=[]){return keys.map(k=>{const s=SOURCES[k];return s?`<li>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`:esc(s.title)}${s.note?`<br><span class="small">${esc(s.note)}</span>`:''}</li>`:''}).join('')}
function imageSrc(name){return globalThis.ZEITSPUREN_ASSETS?.[name]||'assets/'+name}
function diagramHtml(e){return `<figure class="thinking-figure"><svg viewBox="0 0 500 280" role="img" aria-label="${esc('Denkbild: '+e.diagram.join(' – '))}"><rect width="500" height="280" rx="18" fill="#e7efed"/><path d="M65 65 Q435 65 435 140 T65 220" fill="none" stroke="#b56643" stroke-width="3" stroke-dasharray="7 7"/>${e.diagram.map((v,i)=>`<circle cx="48" cy="${55+i*82}" r="18" fill="#1b3b42"/><text x="48" y="${61+i*82}" text-anchor="middle" fill="white" font-size="16">${i+1}</text><rect x="80" y="${29+i*82}" width="390" height="52" rx="8" fill="white"/><text x="96" y="${61+i*82}" fill="#19343d" font-size="17" font-family="sans-serif">${esc(v)}</text>`).join('')}</svg><figcaption>Didaktisches Denkbild · eigens erstellt. Die Verbindung ist eine Untersuchungsfrage, kein bewiesener Ablauf und keine historische Rekonstruktion.</figcaption></figure>`}
function imageHtml(e){if(!e.image)return e.diagram?diagramHtml(e):'';const a=assets[e.image];let caption=a?`${esc(a.motif)}. ${esc(a.image_date)}. ${esc(a.author)} · ${a.license_url?`<a href="${esc(a.license_url)}" target="_blank" rel="noopener">${esc(a.license)}</a>`:esc(a.license)} · <a href="${esc(a.source_page)}" target="_blank" rel="noopener">Bildnachweis</a>. ${esc(a.source_criticism)}`:`Bild aus der bereitgestellten Unterrichtsvorlage, ${e.image.includes('6-')?'S. 6':'S. 5'}. Urheberschaft und genaue Bilddatierung dort nicht ausgewiesen; keine freie Nutzungslizenz belegt.`;if(e.id==='ai')caption='KI-GENERIERT · Meysam Azarneshin / Adobe Stock. Im bereitgestellten NZZ-Artikel vom 13.11.2023 abgebildet. Als Gegenstand der Bildkritik wiedergegeben, kein Ereignisfoto. Keine freie Nutzungslizenz belegt.';return `<figure><img src="${esc(imageSrc(e.image))}" alt="${esc(a?.motif||e.title)}${e.id==='ai'?' – ausdrücklich KI-generiert':''}"><figcaption>${caption}</figcaption></figure>`}
// Numeric century groups are navigation windows, never epoch definitions.
let centurySize=500,centurySelection=null;
function centuryGroups(){
 const upper=Math.max(2026,...state.own.map(e=>Number.isFinite(e.end)?e.end:e.year).filter(Number.isFinite)),groups=[{id:'early',from:-100000,to:-2001,label:'Vor 2000 v. u. Z.'}];
 for(let start=-2000;start<0;start+=centurySize)groups.push({id:String(start),from:start,to:start+centurySize-1,label:Math.abs(start)+'–'+Math.abs(start+centurySize-1)+' v. u. Z.'});
 for(let start=1;start<=upper;start+=centurySize)groups.push({id:String(start),from:start,to:start+centurySize-1,label:start+'–'+(start+centurySize-1)});
 return groups;
}
function centuryVisible(e){if(!Number.isFinite(e.year)||centurySelection===null)return true;const end=Number.isFinite(e.end)?e.end:e.year;return centuryGroups().some(g=>centurySelection.has(g.id)&&e.year<=g.to&&end>=g.from)}
function centuryDomain(){if(centurySelection===null||!centurySelection.size)return null;const chosen=centuryGroups().filter(g=>centurySelection.has(g.id));if(!chosen.length)return null;return [Math.max(Math.min(-18000,...state.own.map(e=>e.year).filter(Number.isFinite)),Math.min(...chosen.map(g=>g.from))),Math.max(...chosen.map(g=>g.to))]}
function renderCenturyControls(){
 const container=$('#centuryControls');if(!container)return;container.hidden=representation!=='timeline';
 $$('[data-period-preset]').forEach(el=>el.innerHTML='<option value="">Zeitgruppe übernehmen …</option>'+periodOptions());
 const groups=centuryGroups();$('#centuryChoices').innerHTML=groups.map(g=>`<div class="century-chip"><label><input type="checkbox" data-century="${g.id}" ${centurySelection===null||centurySelection.has(g.id)?'checked':''}><span>${g.label}</span></label><button data-century-solo="${g.id}" aria-label="Nur ${g.label} anzeigen" aria-pressed="${centurySelection?.size===1&&centurySelection.has(g.id)}">Solo</button></div>`).join('');
 $('#centuryStatus').textContent=centurySelection===null?'Gesamte Zeit':centurySelection.size+(centurySelection.size===1?' Zeitgruppe':' Zeitgruppen')+' · nicht gewählte Zwischenräume bleiben zeitlich erhalten';
}
function initCenturyControls(){
 const panel=document.createElement('section');panel.id='centuryControls';panel.setAttribute('aria-label','Numerische Jahrhundertgruppen');panel.innerHTML=`<div class="century-heading"><strong>Jahrhundertgruppen</strong><label>Gruppengrösse <select id="centurySize"><option value="200">2 Jahrhunderte</option><option value="500" selected>5 Jahrhunderte</option><option value="1000">10 Jahrhunderte</option></select></label><span>Numerische Zeitfenster · keine Epochen</span></div><div id="centuryChoices"></div><div class="century-actions"><button id="centuryAll">Alle einschalten</button><button id="centuryNone">Alle ausschalten</button><span id="centuryStatus" aria-live="polite"></span></div>`;
 $('.category-filter').after(panel);
 const update=()=>{render();$('#scroll').scrollTo({left:0,top:0})};
 panel.onchange=e=>{if(e.target.id==='centurySize'){centurySize=Number(e.target.value);centurySelection=null;update();return}const id=e.target.dataset.century;if(!id)return;if(centurySelection===null)centurySelection=new Set(centuryGroups().map(g=>g.id));if(e.target.checked)centurySelection.add(id);else centurySelection.delete(id);update()};
 panel.onclick=e=>{const solo=e.target.closest('[data-century-solo]');if(solo){centurySelection=new Set([solo.dataset.centurySolo]);update()}};
 $('#centuryAll').onclick=()=>{centurySelection=null;update()};$('#centuryNone').onclick=()=>{centurySelection=new Set();update()};renderCenturyControls();
}

let periodCompare=false,comparePeriods=[{from:1701,to:1800},{from:1901,to:2000}];
function periodContains(e,p){return Number.isFinite(e.year)&&e.year<=p.to&&(Number.isFinite(e.end)?e.end:e.year)>=p.from}
function periodDuration(p){return astronomical(p.to)-astronomical(p.from)}
function periodPosition(year,p,width){const duration=Math.max(1,...comparePeriods.map(periodDuration));return 180+(astronomical(year)-astronomical(p.from))/duration*(width-400)}
function periodOptions(){return centuryGroups().filter(g=>g.id!=='early').map(g=>`<option value="${g.from},${g.to}">${g.label}</option>`).join('')}
function initPeriodCompare(){
 const button=document.createElement('button');button.id='periodCompareToggle';button.textContent='Zwei Zeiträume vergleichen ⇄';$('.century-heading').append(button);
 const controls=document.createElement('section');controls.id='periodCompareControls';controls.hidden=true;controls.innerHTML=`<form id="periodCompareForm">${['A','B'].map((label,i)=>`<fieldset><legend>Zeitraum ${label}</legend><select data-period-preset="${i}" aria-label="Jahrhundertgruppe ${label} übernehmen"><option value="">Zeitgruppe übernehmen …</option>${periodOptions()}</select><label>Von <input id="periodFrom${i}" type="number" required min="-100000" max="10000" value="${comparePeriods[i].from}"></label><label>Bis <input id="periodTo${i}" type="number" required min="-100000" max="10000" value="${comparePeriods[i].to}"></label></fieldset>`).join('')}<button type="submit">Vergleichen</button><button type="button" id="periodSwap">A ⇅ B</button></form><p id="periodCompareHelp">Beide Anfänge liegen übereinander. Gleiche Abstände bedeuten gleich viele Jahre, nicht gleiche historische Bedeutung. Jahreszahlen vor unserer Zeitrechnung negativ eingeben.</p><p id="periodCompareError" role="alert"></p>`;
 $('#centuryControls').after(controls);
 const stage=document.createElement('div');stage.id='periodCompareStage';stage.hidden=true;$('#scroll').after(stage);
 button.onclick=()=>{periodCompare=!periodCompare;if(periodCompare&&centurySelection?.size===2){comparePeriods=centuryGroups().filter(g=>centurySelection.has(g.id)).map(g=>({from:g.from,to:g.to}));syncPeriodInputs()}render()};
 controls.onchange=e=>{const i=e.target.dataset.periodPreset;if(i===undefined||!e.target.value)return;const [from,to]=e.target.value.split(',').map(Number);$('#periodFrom'+i).value=from;$('#periodTo'+i).value=to};
 $('#periodCompareForm').onsubmit=e=>{e.preventDefault();const next=[0,1].map(i=>({from:Number($('#periodFrom'+i).value),to:Number($('#periodTo'+i).value)}));if(next.some(p=>!Number.isInteger(p.from)||!Number.isInteger(p.to)||p.from===0||p.to===0||p.to<p.from||p.from< -100000||p.to>10000)){$('#periodCompareError').textContent='Gültige ganze Jahre ohne Jahr null eingeben; das Ende darf nicht vor dem Anfang liegen.';return}comparePeriods=next;$('#periodCompareError').textContent='';render()};
 $('#periodSwap').onclick=()=>{comparePeriods.reverse();syncPeriodInputs();render()};
}
function syncPeriodInputs(){comparePeriods.forEach((p,i)=>{$('#periodFrom'+i).value=p.from;$('#periodTo'+i).value=p.to})}
function syncPeriodCompare(){
 const on=representation==='timeline'&&periodCompare;document.body?.classList.toggle('period-comparison-active',on);
 if($('#periodCompareControls'))$('#periodCompareControls').hidden=!on;
 if($('#periodCompareStage'))$('#periodCompareStage').hidden=!on;
 if($('#periodCompareToggle')){$('#periodCompareToggle').textContent=on?'Zum einzelnen Zeitstrahl ↩':'Zwei Zeiträume vergleichen ⇄';$('#periodCompareToggle').setAttribute('aria-pressed',String(on))}
 if(on){$('#scroll').hidden=true;$('.timeline-nav').hidden=true;$('#timelineUndated').hidden=true;$('.timeline-caption').hidden=true;$$('.viewoptions label').forEach(el=>{if(el.querySelector('#scale'))el.hidden=true})}
}
function renderPeriodCompare(){
 const width=2600*Number($('#zoom').value),corpus=lensItems($('#search').value,onlyOwn),counts=[];
 $('#periodCompareStage').innerHTML=comparePeriods.map((p,index)=>{const items=corpus.filter(e=>periodContains(e,p));counts.push(items.length);const map=y=>periodPosition(y,p,width),duration=periodDuration(p),longest=Math.max(1,...comparePeriods.map(periodDuration));
 let html=`<div class="compare-axis" style="width:${width}px">${Array.from({length:6},(_,i)=>{const elapsed=Math.round(longest*i/5);if(elapsed>duration)return '';const astro=astronomical(p.from)+elapsed,year=astro<=0?astro-1:astro;return `<span style="left:${map(year)}px">${yr(year)}<small>+${elapsed} Jahre</small></span>`}).join('')}</div>`;
 for(const [id,label,,color] of LANES){if(!visibleCategories.has(id))continue;const lane=items.filter(e=>e.lane===id),slots=[];let cards='';for(const e of lane){const x=map(Math.max(p.from,e.year));let row=slots.findIndex(end=>end+10<x);if(row<0)row=slots.length;slots[row]=x+170;cards+=`<button class="period-compare-event" data-event="${esc(e.id)}" style="left:${x}px;top:${8+row*88}px;border-color:${color}" title="${esc(e.title)}">${e.image?`<img src="${esc(imageSrc(e.image))}" alt="">`:''}<span><time>${esc(e.date||yr(e.year))}</time><strong>${esc(e.title)}</strong></span></button>`}
 html+=`<div class="compare-lane" style="height:${Math.max(65,slots.length*88+12)}px;width:${width}px"><div class="lane-name">${label}</div><div class="compare-extent" style="left:180px;width:${Math.max(1,map(p.to)-180)}px"></div>${cards}${!lane.length?'<p class="compare-empty">Keine Spuren im gewählten Bestand.</p>':''}</div>`}
 return `<section class="period-panel"><header><strong>${index?'B':'A'} · ${yr(p.from)} – ${yr(p.to)}</strong><span>${items.length} ${items.length===1?'Spur':'Spuren'} · ${duration+1} Kalenderjahre</span></header><div class="period-viewport" tabindex="0" role="region" aria-label="Zeitraum ${index?'B':'A'}; verschiebbar">${html}</div></section>`}).join('');
 $('#count').textContent=`Vergleich A: ${counts[0]} · B: ${counts[1]} Spuren · Kategorien und Suche gelten für beide`;
 $$('#periodCompareStage [data-event]').forEach(b=>b.onclick=()=>openEvent(b.dataset.event));
 const views=$$('.period-viewport');let syncing=false;views.forEach(v=>{v.addEventListener('scroll',()=>{if(syncing)return;syncing=true;views.forEach(other=>{if(other!==v)other.scrollLeft=v.scrollLeft});syncing=false});v.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();setTimelineZoom(Number($('#zoom').value)*Math.exp(-e.deltaY*.005),e.clientX-v.getBoundingClientRect().left)}},{passive:false});let drag=null;v.onpointerdown=e=>{if(e.button||e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,left:v.scrollLeft,top:v.scrollTop};v.setPointerCapture(e.pointerId)};v.onpointermove=e=>{if(drag){v.scrollLeft=drag.left+drag.x-e.clientX;v.scrollTop=drag.top+drag.y-e.clientY}};v.onpointerup=v.onpointercancel=()=>drag=null;});
}
function mapFn(width){const left=180,span=width-400,domain=centuryDomain();if(domain)return y=>left+(astronomical(y)-astronomical(domain[0]))/(astronomical(domain[1])-astronomical(domain[0]))*span;let low=Math.min(-18000,...state.own.map(e=>e.year)),high=Math.max(2050,...state.own.map(e=>e.end||e.year));if($('#scale').value==='linear')return y=>left+(astronomical(y)-astronomical(low))/(astronomical(high)-astronomical(low))*span;const anchors=[[low,0],[-10000,.08],[-7000,.16],[-3500,.24],[1,.36],[600,.44],[1000,.51],[1400,.61],[1600,.70],[1800,.79],[1900,.88],[high,1]];return y=>{for(let i=1;i<anchors.length;i++){if(y<=anchors[i][0]){const [a,x]=anchors[i-1],[b,z]=anchors[i];return left+(x+(y-a)/(b-a)*(z-x))*span}}return left+span}}
function render(){
 prepareRepresentation();syncTimelineStudio();renderCenturyControls();syncPeriodCompare();if(representation!=='timeline'){renderMode();return;}
 if(periodCompare){renderPeriodCompare();return;}
 const width=2600*Number($('#zoom').value),map=mapFn(width),query=$('#search').value.toLocaleLowerCase('de');const visible=lensItems(query,onlyOwn).filter(centuryVisible),items=visible.filter(e=>Number.isFinite(e.year)),undated=visible.filter(e=>!Number.isFinite(e.year));
 $('#timeline').style.width=width+'px';const domain=centuryDomain();$$('.viewoptions label').forEach(el=>{if(el.querySelector('#scale'))el.hidden=!!domain});$('.timeline-nav').hidden=!!domain;const ticks=domain?Array.from({length:6},(_,i)=>Math.round(domain[0]+i*(domain[1]-domain[0])/5)).filter(y=>y!==0):$('#scale').value==='linear'?[-15000,-10000,-5000,1,2023]:[-17000,-10000,-7000,-3200,1,476,868,1200,1492,1789,1914,2023];let html=`<div class="axis">${ticks.map(y=>`<span class="tick" style="left:${map(y)}px">${yr(y)}</span>`).join('')}</div>`;
 const ends=[-18000,-800,...state.bounds,2050],names=['Vor- / Frühgeschichte?','Antike (regional)','Mittelalter','Frühe Neuzeit','Moderne','Zeitgeschichte'];html+=`<div class="lane" style="height:68px"><div class="lane-name">Epochenentwurf<small>Europa · veränderbar</small></div>${names.map((n,i)=>domain&&(ends[i]>domain[1]||ends[i+1]<domain[0])?'':`<button class="periodbar" data-epoch style="left:${map(domain?Math.max(domain[0],ends[i]):ends[i])}px;width:${Math.max(35,map(domain?Math.min(domain[1],ends[i+1]):ends[i+1])-map(domain?Math.max(domain[0],ends[i]):ends[i])-2)}px" title="${n}: ${yr(ends[i])} bis ${yr(ends[i+1])}; Grenzen hinterfragen">${n}</button>`).join('')}</div>`;
 for(const [id,label,sub,color] of LANES){if(!visibleCategories.has(id))continue;const laneItems=items.filter(e=>e.lane===id).sort((a,b)=>a.year-b.year);let slots=[],cards='';for(const e of laneItems){const x=map(domain?Math.max(domain[0],e.year):e.year);let row=slots.findIndex(end=>end+12<x);if(row<0)row=slots.length;slots[row]=x+176;cards+=`<button class="event ${e.image?'':'noimg'} ${selected===e.id?'selected':''}" data-event="${esc(e.id)}" style="left:${x}px;top:${12+row*146}px;--laneColor:${color}" aria-label="${esc(e.date||yr(e.year))}: ${esc(e.title)}">${e.image?`<img src="${esc(imageSrc(e.image))}" alt="" loading="lazy">`:''}${mediaBadge(e)}<span class="event-text"><time>${esc((e.own?'MEINE SPUR · ':'')+((e.date||'').startsWith('ca.')||(e.date||'').startsWith('um ')?'ca. ':'')+yr(e.year))}</time><strong>${esc(e.title)}</strong></span></button>`;if(e.end&&e.end>e.year)cards+=`<div title="Zeitraum bis ${yr(e.end)}" style="position:absolute;left:${x}px;top:${150+row*146}px;width:${Math.max(3,map(e.end)-x)}px;height:3px;background:${color}"></div>`}
 const height=Math.max(100,slots.length*146+16);html+=`<div class="lane" style="height:${height}px"><div class="lane-name">${label}<small>${id==='ideas'?'Text- und Bezugsdaten · keine Fortschrittsfolge':sub}</small></div>${cards}${onlyOwn&&!laneItems.length?'<p class="empty">Hier ist noch Platz für deine Spuren.</p>':''}</div>`}
 html+=state.bounds.filter(y=>!domain||(y>=domain[0]&&y<=domain[1])).map(y=>`<div class="boundary" style="left:${map(y)}px"></div>`).join('');$('#timeline').innerHTML=html;
 $('#timelineUndated').innerHTML=timelineUndatedHtml(undated);$$('#timeline [data-event],#timelineUndated [data-event]').forEach(b=>b.onclick=()=>openEvent(b.dataset.event));$$('[data-epoch]').forEach(b=>b.onclick=openEpochs);$('#count').textContent=`${visible.length} von ${lensCorpus().length} Spuren · ${items.length} datiert · ${undated.length} ohne Datierung${onlyOwn?' · nur eigene Einträge':''}`;
 $('#scaleHint').textContent=domain?'Ausgewählte Zeitspanne: Jahresabstände proportional · Jahrhundertgruppen sind keine Epochen.':$('#scale').value==='linear'?'Proportionale Jahresachse: Gleiche Abstände bedeuten gleich viele Jahre.':'Leseraster: Zeitabstände sind unterschiedlich stark gedehnt.';
}
function noteBox(key,label='Dein Denkprotokoll'){return `<label for="note">${label}</label><textarea id="note" placeholder="Meine Behauptung … Mein Beleg … Eine andere Deutung … Meine offene Frage …">${esc(state.notes[key]||'')}</textarea><p class="small">Automatisch auf diesem Gerät gespeichert. Keine Bewertung nach Stichwörtern: Entscheidend sind Begründung, Belege und Gegenargumente.</p>`}
function attachNote(key){$('#note').oninput=e=>{state.notes[key]=e.target.value;save()}}
function materialsHtml(id){return (state.materials[id]||[]).map((m,i)=>`<div class="attachment">${m.type.startsWith('image/')?`<img src="${m.data}" alt="${esc(m.description||m.name)}">`:m.type.startsWith('audio/')?`<audio controls preload="metadata" src="${m.data}" aria-label="${esc(m.name)}"></audio>`:m.type.startsWith('video/')?`<video controls playsinline preload="metadata" src="${m.data}" aria-label="${esc(m.name)}"></video>`:''}<div><a href="${m.data}" download="${esc(m.name)}">${esc(m.name)}</a><p class="small">${esc(m.description||'Keine Herkunftsangabe ergänzt.')}</p><button class="removeMaterial small" data-index="${i}">Material entfernen</button></div></div>`).join('')}
function authorHtml(e){if(!e.reading&&!['macrohistory','harariorders','hararipaths'].includes(e.id))return '';return `<aside class="author-intro" aria-label="Einführung zu Harari"><div class="author-label"><span>SAPIENS</span><small>Ein Autor · eine grosse Frage</small></div><div><p class="eyebrow">YUVAL NOAH HARARI · HISTORIKER, *1976</p><h3>Wie können Fremde gemeinsam eine Welt schaffen?</h3><p>Harari ist ein israelischer Historiker. In <em>Eine kurze Geschichte der Menschheit</em> (deutsch 2013) fragt er, wie der Homo sapiens so mächtig werden konnte. Seine zentrale Idee: Menschen können gemeinsame Vorstellungen und Regeln entwickeln, die Zusammenarbeit über persönliche Bekanntschaften hinaus ermöglichen.</p><p>Eine Banknote funktioniert etwa, weil Menschen und Institutionen ihre Gültigkeit anerkennen. Harari nennt solche zwischen Menschen geteilten Ordnungen <strong>intersubjektiv</strong>. Er fragt zugleich, ob mehr Macht, Produktion und Wissen auch ein besseres Leben bedeuten. Gerade diesen Zusammenhang hält er für offen.</p><details><summary>Seinen Ansatz und seine Grenzen kennenlernen</summary>${HARARI_INTRO.paragraphs.map(([title,text])=>`<h4>${esc(title)}</h4><p>${esc(text)}</p>`).join('')}<p class="small">${esc(HARARI_INTRO.text)}</p><ul class="source-list">${sourceHtml(HARARI_INTRO.sources)}</ul></details></div></aside>`}
function readingHtml(e){if(!e.reading)return '';const [ref,title,thesis,limit,question]=e.reading;return `<details class="reading-note"><summary>Bei Harari nachlesen: ${esc(title)}</summary><p>${esc(thesis)}</p><p>${esc(limit)}</p><p class="small">${esc(ref)} · deutsche Ausgabe 2013. Gezählt sind die Seiten der bereitgestellten PDF-Datei.</p></details>`}
function activityHtml(e){const a=e.activity;if(!a)return `<section class="tasks"><h3>Deine Quelle weiter untersuchen</h3><p>Halte fest, welche Aussage dein Material stützt und welche Frage es offenlässt.</p>${noteBox(e.id)}</section>`;return `<section class="inquiry"><p class="eyebrow">${HISTORICAL_MEDIA[e.id]?'MIT BILD UND TON ARBEITEN':e.image?'MIT DEM BILD ARBEITEN':'EIN FALL ZUM UNTERSUCHEN'}</p><h3>${esc(a.title)}</h3><p class="inquiry-scene">${esc(a.scene)}</p><div class="evidence-board">${a.cards.map(c=>`<article class="evidence-card"><h4>${esc(c.label)}</h4><p>${esc(c.text)}</p></article>`).join('')}</div><div class="inquiry-steps">${a.steps.map((step,i)=>`<article><span class="step-number">${i+1}</span><div><h4>${esc(step.label)}</h4><p>${esc(step.text)}</p></div></article>`).join('')}</div><div class="work-result"><span>DEIN ERGEBNIS</span><p>${esc(a.result)}</p></div><details class="help-note"><summary>Ein Hinweis, wenn du feststeckst</summary><p>${esc(a.hint)}</p></details>${noteBox(e.id,'Deine Bearbeitung: '+a.title)}</section>`}
function openEvent(id){if(byId(id))lensFocus=id;
 if(id.startsWith('mode-')||id.startsWith('lens-')||id.startsWith('telos-')||id.startsWith('premise-')){popup.close();reopenModeNote(id);return;}
 const e=byId(id);if(!e)return;currentId=id;const ordered=all().filter(x=>x.id!==id).sort((a,b)=>Math.abs(a.year-e.year)-Math.abs(b.year-e.year));const prev=all().filter(x=>x.year<e.year).sort((a,b)=>b.year-a.year)[0],next=all().filter(x=>x.year>e.year).sort((a,b)=>a.year-b.year)[0];const rel=[...new Set([...(e.related||[]),prev?.id,next?.id].filter(Boolean))].filter(x=>x!==id);
 const img=e.image?imageHtml(e):'';const prompt=e.tasks||['Welche Aussage lässt sich mit deinem Material belegen?','Welche Perspektive bleibt offen?','Welche Beziehung zu einer benachbarten Spur kannst du begründen?'];
 show(`<p class="metadata">${esc(e.date|| (e.year?yr(e.year):'BEGRIFFSWERKSTATT'))}${e.end?' bis '+yr(e.end):''}${e.own?' · EIGENER EINTRAG':''}</p><h2 id="dialogTitle">${esc(e.title)}</h2><p class="lead">${esc(e.intro||e.question||'Welche Geschichte lässt sich hier erzählen?')}</p>${authorHtml(e)}<div class="${img?'popupgrid':''}"><div><p>${esc(e.text)}</p>${e.evidence?`<div class="notice"><strong>Genauer hinsehen</strong><p>${esc(e.evidence)}</p></div>`:''}${e.source?`<p class="small"><strong>Herkunft:</strong> ${esc(e.source)}</p>`:''}${e.perspective?`<p><strong>Perspektive:</strong> ${esc(e.perspective)}</p>`:''}${e.uncertainty?`<p><strong>Unsicherheit:</strong> ${esc(e.uncertainty)}</p>`:''}</div>${img}</div>${e.visualQuestion?`<aside class="visual-question"><strong>Am Bild weiterdenken</strong><p>${esc(e.visualQuestion)}</p></aside>`:''}${mediaHtml(e)}${readingHtml(e)}${activityHtml(e)}<h3>In Beziehung setzen</h3><p class="small">Die zeitlich nächsten Einträge sind eine Auswahl dieses Zeitstrahls, keine vollständige Geschichte. Nachbarschaft beweist keine Kausalität.</p><p class="small">${prev?`Vorher: ${esc(prev.title)} (${yr(prev.year)}). `:''}${next?`Nachher: ${esc(next.title)} (${yr(next.year)}).`:''}</p><div class="related">${rel.map(r=>`<button data-open="${esc(r)}">${esc(byId(r)?.title||r)} ↗</button>`).join('')}</div><div class="actions"><button id="compareThis">Mit anderer Spur vergleichen</button><button id="addMaterial">＋ Material ergänzen</button>${e.own?'<button id="editEvent">Eintrag bearbeiten</button><button class="danger" id="deleteEvent">Eintrag löschen</button>':''}</div><div id="materials">${materialsHtml(id)}</div>${state.relations.filter(r=>r.a===id||r.b===id).map(r=>`<div class="notice"><strong>${esc(r.type)}: ${esc(byId(r.a)?.title)} ↔ ${esc(byId(r.b)?.title)}</strong><p>${esc(r.claim)}</p><p class="small">Beleg: ${esc(r.evidence)} · Grenze: ${esc(r.counter)}</p></div>`).join('')}<details><summary>Quellen und Einordnung</summary><p class="small">Didaktische Paraphrasen, keine Originalzitate, sofern nicht ausdrücklich bezeichnet.</p><ul class="source-list">${sourceHtml(e.sources)}</ul></details>`);
 const modelFor={medievalworld:'medieval',egyptworld:'egypt',materialism:'materialism',augustine:'present',braudel:'layers',hegel:'direction',koselleck:'direction',hararipaths:'direction',nietzsche:'recurrence',recurrence:'recurrence',timeforms:'network',halbwachs:'memoria',assmann:'memoria'};if(modelFor[id]){const jump=document.createElement('div');jump.className='mode-jump';jump.innerHTML='<p>Diesen Ansatz in einer anderen Darstellungsform erproben.</p><button id="openModel">Darstellung wechseln ↗</button>';body.querySelector('.lead').after(jump);$('#openModel').onclick=()=>{popup.close();switchRepresentation(modelFor[id])};}
 if(id==='timeforms'){const block=document.createElement('section');block.innerHTML='<label for="timeModel">Darstellungsform wechseln</label><select id="timeModel"><option value="line">Linie – Reihenfolge</option><option value="cycle">Kreis – Wiederkehr</option><option value="layers">Zeitschichten – verschiedene Tempi</option></select><div id="modelDrawing"></div>';body.querySelector('.inquiry').before(block);$('#timeModel').onchange=()=>drawTimeModel($('#timeModel').value);drawTimeModel('line')}
 wireHistoricalMedia(e);attachNote(id);if(e.activity)$('#note').placeholder=e.activity.result;$('#compareThis').onclick=()=>openCompare(e.year!==undefined?id:'columbus');$('#addMaterial').onclick=()=>openMaterial(id);body.querySelectorAll('.removeMaterial').forEach(b=>b.onclick=()=>{state.materials[id].splice(Number(b.dataset.index),1);save();openEvent(id)});if(e.own){$('#editEvent').onclick=()=>openForm(e);$('#deleteEvent').onclick=()=>showDelete(e)}
}
function openForm(e={}){
 const edit=!!e.id;show(`<h2 id="dialogTitle">${edit?'Deine Spur bearbeiten':'Eine eigene Spur setzen'}</h2><p class="lead">Ein Datum verorten. Eine Frage öffnen. Einen Zusammenhang begründen.</p><form id="eventForm" class="formgrid"><div class="full"><label for="title">Titel *</label><input id="title" name="title" required maxlength="120" value="${esc(e.title)}" placeholder="Zum Beispiel: Ein Denkmal in meinem Wohnort"></div><div><label for="year">Jahr * (vor unserer Zeitrechnung: negativ)</label><input id="year" name="year" type="number" min="-100000" max="10000" step="1" required value="${e.year??''}" placeholder="z. B. 1848 oder -500"></div><div><label for="end">Endjahr (optional)</label><input id="end" name="end" type="number" min="-100000" max="10000" step="1" value="${e.end??''}"></div><div><label for="region">Spur *</label><select id="region" name="lane">${LANES.map(([v,l])=>`<option value="${v}" ${e.lane===v?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="dateLabel">Datierung genauer angeben</label><input id="dateLabel" name="date" value="${esc(e.date)}" placeholder="z. B. um 1450 / Ereignis 1492, Bild 1847"></div><div class="full"><label for="question">Meine historische Frage *</label><input id="question" name="question" required value="${esc(e.question)}" placeholder="Was möchte ich an dieser Spur untersuchen?"></div><div class="full"><label for="text">Ereignis, Prozess oder Darstellung *</label><textarea id="text" name="text" required>${esc(e.text)}</textarea></div><div><label for="perspective">Perspektive / betroffene Gruppen</label><textarea id="perspective" name="perspective">${esc(e.perspective)}</textarea></div><div><label for="source">Quelle / Herkunft / Urheber*in *</label><textarea id="source" name="source" required placeholder="Titel, Datum, Seite oder URL. Fehlende Angaben als unbekannt kennzeichnen.">${esc(e.source)}</textarea></div><div class="full"><label for="uncertainty">Was ist unsicher? Was wäre eine andere Deutung?</label><textarea id="uncertainty" name="uncertainty">${esc(e.uncertainty)}</textarea></div><p class="small full">Kein Jahr null. Einträge ausserhalb des bisherigen Ausschnitts erweitern die Achse. Dateien kannst du danach im Popup ergänzen.</p><div class="full actions"><button type="submit" class="primary">${edit?'Änderungen speichern':'Eintrag setzen'}</button><button type="button" id="cancelForm">Abbrechen</button></div><p class="full danger" id="formError" role="alert"></p></form>`,'DEINE MATERIALIEN');
 $('#cancelForm').onclick=()=>edit?openEvent(e.id):popup.close();$('#eventForm').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));const year=Number(f.year),end=f.end?Number(f.end):null;if(year===0||end===0){$('#formError').textContent='Die verwendete Jahreszählung hat kein Jahr null.';return}if(end!==null&&end<year){$('#formError').textContent='Das Endjahr darf nicht vor dem Anfang liegen.';return}const event={...f,year,end,id:e.id||uid(),own:true};if(edit)state.own=state.own.map(x=>x.id===e.id?event:x);else state.own.push(event);await save();render();openEvent(event.id);toast('Deine Spur ist eingetragen.');};
}
function showDelete(e){show(`<h2 id="dialogTitle">Eintrag entfernen?</h2><p>«${esc(e.title)}» und seine Materialien, Notizen und Verbindungen werden aus diesem Arbeitsstand entfernt. Ein zuvor exportierter Arbeitsstand bleibt erhalten.</p><div class="actions"><button class="danger" id="confirmDelete">Eintrag entfernen</button><button id="cancelDelete">Behalten</button></div>`);$('#cancelDelete').onclick=()=>openEvent(e.id);$('#confirmDelete').onclick=async()=>{state.own=state.own.filter(x=>x.id!==e.id);delete state.notes[e.id];for(const mode of Object.keys(GLOBAL_LENSES)){delete state.notes[lensNoteKey(mode,e.id)];if(state.lensAssignments[mode])delete state.lensAssignments[mode][e.id]}for(const [mode,b] of Object.entries(state.interpretations||{}))for(const p of b.profiles){delete p.decisions[e.id];delete p.assignments[e.id];delete p.notes[lensNoteKey(mode,e.id)]}delete state.materials[e.id];state.relations=state.relations.filter(r=>r.a!==e.id&&r.b!==e.id);await save();render();popup.close();toast('Eintrag entfernt.')}}
function openMaterial(id){show(`<h2 id="dialogTitle">Material zur Spur ergänzen</h2><p>${esc(byId(id).title)}</p><form id="materialForm"><label for="materialFile">Bild, PDF, Text, MP3 oder Kurzvideo (max. 8 MB) *</label><input id="materialFile" type="file" accept="image/jpeg,image/png,image/webp,application/pdf,text/plain,audio/mpeg,video/mp4,video/webm" required><label for="materialDescription">Herkunft und Einordnung *</label><textarea id="materialDescription" required placeholder="Wer hat das Material erstellt? Wann? Was stellt es dar? Original, spätere Darstellung, KI-generiert? Nutzungsrecht? Welche Behauptung lässt sich prüfen?"></textarea><p class="small">Dateien bleiben im Browser auf diesem Gerät. Beim Export werden sie in die Sicherung aufgenommen. Für unbekannte Herkunft bitte ausdrücklich «unbekannt» eintragen.</p><div class="actions"><button type="submit" class="primary">Material speichern</button><button type="button" id="backMaterial">Zurück</button></div><p id="materialError" class="danger" role="alert"></p></form>`,'EIGENE QUELLEN');$('#backMaterial').onclick=()=>openEvent(id);$('#materialForm').onsubmit=async ev=>{ev.preventDefault();const f=$('#materialFile').files[0];if(!f||f.size>8*1024*1024||!validMime(f.type)){$('#materialError').textContent='Bitte JPEG, PNG, WebP, PDF, TXT, MP3, MP4 oder WebM bis 8 MB auswählen.';return}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});(state.materials[id]??=[]).push({name:f.name,type:f.type,data,description:$('#materialDescription').value});await save();openEvent(id);toast('Material ergänzt.')}catch(e){$('#materialError').textContent='Die Datei konnte nicht gelesen werden.'}}}
const validMime=t=>['image/jpeg','image/png','image/webp','application/pdf','text/plain','audio/mpeg','video/mp4','video/webm'].includes(t);
function openCompare(first='columbus',second='haiti'){
 const opts=chosen=>lensCorpus().sort((a,b)=>(a.year??Infinity)-(b.year??Infinity)).map(e=>`<option value="${esc(e.id)}" ${e.id===chosen?'selected':''}>${e.year?yr(e.year):'Begriff'} · ${esc(e.title)}</option>`).join('');show(`<h2 id="dialogTitle">Zwei Spuren, ein Zusammenhang</h2><p class="lead">Zeitliche Nähe ist ein Ausgangspunkt. Eine Beziehung braucht Argumente.</p><form id="compareForm"><div class="comparegrid"><div><label for="compareA">Erste Spur</label><select id="compareA">${opts(first)}</select></div><div><label for="compareB">Zweite Spur</label><select id="compareB">${opts(second===first?'print':second)}</select></div></div><div id="comparePreview"></div><label for="relationType">Art der Beziehung</label><select id="relationType"><option>Vergleich</option><option>Gleichzeitigkeit</option><option>Kontinuität</option><option>Wandel / Bruch</option><option>Ursache / Folge (zu belegen)</option><option>Erinnerung / spätere Darstellung</option><option>Verflechtung / Austausch</option></select><label for="claim">Meine begründete Aussage *</label><textarea id="claim" required placeholder="Die beiden Spuren hängen zusammen, weil …"></textarea><label for="evidence">Belege / noch nötige Quellen *</label><textarea id="evidence" required placeholder="Das wird gestützt durch … / Prüfen müsste ich …"></textarea><label for="counter">Grenze des Vergleichs / Gegenargument *</label><textarea id="counter" required placeholder="Der Vergleich erklärt nicht … / Dagegen spricht …"></textarea><button type="submit" class="primary">Verbindung festhalten</button><p id="compareError" class="danger" role="alert"></p></form>`,'VERGLEICHEN UND BEGRÜNDEN');
 function preview(){const a=byId($('#compareA').value),b=byId($('#compareB').value);$('#comparePreview').innerHTML=`<div class="notice"><strong>${a.year&&b.year?yearDiff(a.year,b.year).toLocaleString('de-CH')+' Jahre Abstand der gesetzten Bezugspunkte':'Begriffsvergleich ohne gemeinsamen Jahresabstand'}</strong><p class="small">${esc(a.date||(a.year?yr(a.year):'Begriff'))} ↔ ${esc(b.date||(b.year?yr(b.year):'Begriff'))}. Bei Zeiträumen und unsicheren Datierungen ist dies kein exakter Abstand der gesamten Prozesse.</p><div class="comparegrid"><p>${esc(a.intro||a.question||a.title)}</p><p>${esc(b.intro||b.question||b.title)}</p></div></div>`}$('#compareA').onchange=preview;$('#compareB').onchange=preview;preview();$('#compareForm').onsubmit=async ev=>{ev.preventDefault();const a=$('#compareA').value,b=$('#compareB').value;if(a===b){$('#compareError').textContent='Bitte zwei verschiedene Spuren auswählen.';return}state.relations.push({id:uid(),a,b,type:$('#relationType').value,claim:$('#claim').value,evidence:$('#evidence').value,counter:$('#counter').value});await save();render();openEvent(a);toast('Verbindung mit Begründung gespeichert.')}}
function openEpochs(){const labels=['Antike → Mittelalter','Mittelalter → Frühe Neuzeit','Frühe Neuzeit → Moderne','Moderne → Zeitgeschichte'];show(`<h2 id="dialogTitle">Wo beginnt eine neue Zeit?</h2><p class="lead">Verändere den europäischen Epochenentwurf. Begründe zuerst, was deine Grenzen sichtbar machen sollen.</p><p>Die Startwerte 476, 1492, 1789 und 1914 sind verbreitete, aber umstrittene Orientierungen. «Zeitgeschichte» wird häufig über die Zeit der Mitlebenden definiert; 1914 ist deshalb kein allgemeingültiger Beginn. Andere Räume brauchen andere Fragestellungen.</p><form id="epochForm">${labels.map((l,i)=>`<div class="sliderrow"><label for="bound${i}">${l}</label><input id="bound${i}" type="range" min="${[200,1300,1600,1850][i]}" max="${[900,1650,1900,2025][i]}" value="${state.bounds[i]}" step="1"><output id="boundOut${i}">${state.bounds[i]}</output></div>`).join('')}<label for="boundaryReason">Kriterium, Raum, Perspektive – und ein Gegenbeispiel *</label><textarea id="boundaryReason" required placeholder="Ich setze die Grenze …, weil … Für … passt sie, für … nicht. Über die Grenze hinweg bleibt …">${esc(state.boundaryReason)}</textarea><div class="notice">Prüfe mit 868 in China, um 1500 in Timbuktu und 1804 in Haiti: Was wird durch deinen Entwurf sichtbar, was nicht? Die Linien gelten nicht automatisch für die ganze Welt.</div><div class="actions"><button class="primary" type="submit">Epochenentwurf anwenden</button><button type="button" id="resetBounds">Startwerte in die Regler übernehmen</button><button type="button" data-open="period">Begriff Epochen hinterfragen ↗</button></div><p id="epochError" class="danger" role="alert"></p></form>`,'GRENZEN ALS HYPOTHESEN');for(let i=0;i<4;i++)$('#bound'+i).oninput=e=>$('#boundOut'+i).textContent=e.target.value;$('#resetBounds').onclick=()=>[476,1492,1789,1914].forEach((n,i)=>{$('#bound'+i).value=n;$('#boundOut'+i).textContent=n});$('#epochForm').onsubmit=async ev=>{ev.preventDefault();const b=[0,1,2,3].map(i=>Number($('#bound'+i).value));if(b.some((v,i)=>i>0&&v<=b[i-1])){$('#epochError').textContent='Die Grenzen müssen zeitlich aufeinander folgen.';return}state.boundaryHistory.push({bounds:[...state.bounds],reason:state.boundaryReason});state.bounds=b;state.boundaryReason=$('#boundaryReason').value;await save();render();popup.close();toast('Dein begründeter Epochenentwurf ist sichtbar.')}}
function openJournal(){const notes=Object.entries(state.notes).filter(([k,v])=>v.trim());show(`<h2 id="dialogTitle">Mein Denkprotokoll</h2><p class="lead">${notes.length} Notizen · ${state.own.length} eigene Spuren · ${state.relations.length} begründete Verbindungen</p><div class="notice"><strong>Prüfe deine Deutungen</strong><p>Ist die Frage klar? Passen die Belege? Sind Perspektive und Unsicherheiten sichtbar? Gibt es ein Gegenargument? Hat sich deine erste Vermutung verändert?</p></div>${notes.map(([k,v])=>`<h3>${esc(byId(k)?.title||modeNoteLabel(k))}</h3><p style="white-space:pre-wrap">${esc(v)}</p><button data-open="${esc(k)}">Notiz weiterbearbeiten ↗</button>`).join('')||'<p>Noch keine Notizen. Öffne eine Spur und halte deine erste Deutung fest.</p>'}<h3>Meine Epochengrenzen</h3><p>${state.bounds.map(yr).join(' · ')}</p><p>${esc(state.boundaryReason||'Noch keine eigene Begründung.')}</p>${state.boundaryHistory.length?`<details><summary>Frühere Entwürfe (${state.boundaryHistory.length})</summary>${state.boundaryHistory.map(h=>`<p>${h.bounds.map(yr).join(' · ')}<br>${esc(h.reason||'Startentwurf')}</p>`).join('')}</details>`:''}<h3>Meine Verbindungen</h3>${state.relations.map(r=>`<div class="notice"><strong>${esc(byId(r.a)?.title)} ↔ ${esc(byId(r.b)?.title)}</strong><p>${esc(r.type)}: ${esc(r.claim)}</p><p>Beleg: ${esc(r.evidence)}</p><p>Grenze: ${esc(r.counter)}</p><button data-delete-relation="${esc(r.id)}">Verbindung entfernen</button></div>`).join('')||'<p>Noch keine Verbindungen festgehalten.</p>'}<div class="actions"><button id="printJournal">Drucken / als PDF speichern</button><button id="exportJournal">Arbeitsstand mit Materialien exportieren</button></div>`,'DEIN DENKEN WIRD SICHTBAR');$('#printJournal').onclick=()=>window.print();$('#exportJournal').onclick=exportState;$$('[data-delete-relation]').forEach(b=>b.onclick=()=>{state.relations=state.relations.filter(r=>r.id!==b.dataset.deleteRelation);save();render();openJournal()})}
function openSources(){show(`<h2 id="dialogTitle">Quellen, Entscheidungen, offene Fragen</h2><p class="lead">Dieser Zeitstrahl ist selbst eine Auswahl. Du darfst ihn begründet verändern.</p><h3>So arbeitest du hier</h3><p>Öffne eine Spur, untersuche Material und Denkaufträge, notiere eine belegte Deutung und vergleiche sie mit einer zweiten Spur. Ergänze eure Unterrichtsereignisse und Dateien. Nutze die Epochengrenzen als prüfbare Hypothesen. Es gibt keine vorgeschriebene Modulfolge.</p><h3>Quellenkritik – bei jeder Spur</h3><p>Wer hat das Material wann, wo, für wen und wozu hergestellt? Wie gelangte es zu uns? Welche Bearbeitungen, Übersetzungen, Auslassungen und Machtverhältnisse prägen es? Was belegt es, was nicht? Welche weitere Quelle könnte die Deutung prüfen?</p><h3>Bearbeitung der Vorlagen</h3><p>Die beiden bereitgestellten PDFs wurden in neue Fallstudien, Vergleiche und Denkaufträge umgearbeitet. Die Bezeichnung «Entdeckung», die Schriftgrenze, pauschale Aussagen über andere Kulturen und die einfache Subtraktion bei islamischer Zeitrechnung wurden kritisch korrigiert. Der sachfremde Artikel auf der NZZ-Seite wurde nicht übernommen.</p><p id="moodleStatus">Moodle-Kurs «Geschichte HuI, Materialien alle Klassen»: Nach Anmeldung wurde die Ressource «Zeittafeln» (Christoph Pallaske, Version 3.4) vollständig ausgewertet. Daraus entstand die eigene Spur «Auch ein Zeitstrahl hat einen Standpunkt»: räumliche Auswahl, Grenzsetzungen und die Frage nach einem Anfang der Globalisierung werden geprüft. Die beiden bereitgestellten PDFs sind ebenfalls im Kurs verzeichnet. Weitere nur gesichtete Kurstitel werden nicht als inhaltlich ausgewertete Quellen ausgegeben.</p><h3>Wie die Achse ordnet</h3><p>Das Leseraster dehnt Zeitabschnitte unterschiedlich, damit Einträge lesbar bleiben. «Jahre proportional» macht diese Entscheidung sichtbar. Bezugspunkte mit «um» sind Näherungen; Balken eigener Einträge zeigen Zeiträume. Die gemeinsame Jahreszählung kennt kein Jahr null. Regionen sind Arbeitsansichten, keine abgeschlossenen Kulturblöcke; der Zeitstrahl ist ausdrücklich nicht vollständig.</p><h3>Speichern und Austauschen</h3><p>Eigene Daten liegen in diesem Browser auf diesem Gerät (IndexedDB). Es gibt keine Anmeldung und keine automatische Klassensynchronisation. Das Löschen von Browserdaten kann den Arbeitsstand entfernen. Export enthält eigene Einträge, Notizen, Verbindungen und angehängte Dateien. Import ergänzt eigene Spuren; vorhandene Konflikte werden erhalten und nicht still überschrieben.</p><h3>Fachliche Grundlagen</h3><ul class="source-list">${sourceHtml(Object.keys(SOURCES))}</ul><h3>Bildnachweise</h3><p class="small">Vorschaubilder sind für Karten beschnitten; die Popupansicht zeigt das volle Bild. Historische und moderne Bilddatierung werden getrennt. Bilder aus den bereitgestellten PDFs dienen hier der Quellenanalyse; ihre freie Weiterverwendung ist nicht belegt.</p>${Object.values(assets).map(a=>`<p class="small"><strong>${esc(a.motif)}</strong> · ${esc(a.author)} · ${esc(a.image_date)} · ${a.license_url?`<a href="${esc(a.license_url)}" target="_blank" rel="noopener">${esc(a.license)}</a>`:esc(a.license)} · <a href="${esc(a.source_page)}" target="_blank" rel="noopener">Quellseite</a></p>`).join('')}`,'NACHVOLLZIEHBAR ARBEITEN')}
function exportState(){captureReadings();const payload={...state,exportedAt:new Date().toISOString(),app:'Zeitspuren'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`zeitspuren-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Arbeitsstand mit Materialien wird exportiert.')}
function validate(x){if(!x||x.version!==1||!Array.isArray(x.own)||x.own.length>1000)throw Error('Unbekanntes Dateiformat.');const out=defaults();const text=(v,n=30000)=>typeof v==='string'?v.slice(0,n):'';const record=v=>v&&typeof v==='object'&&!Array.isArray(v);const key=v=>typeof v==='string'&&/^[A-Za-z0-9_-]{1,160}$/.test(v)&&!['__proto__','constructor','prototype'].includes(v);const seen=new Set([...EVENTS.map(e=>e.id),...Object.keys(CONCEPTS)]);for(const e of x.own){if(!e||!key(e.id)||e.id.length>100||seen.has(e.id)||!Number.isInteger(e.year)||e.year===0||e.year< -100000||e.year>10000||!LANES.some(l=>l[0]===e.lane))throw Error('Ungültiger Ereigniseintrag.');seen.add(e.id);if(e.end!=null&&(!Number.isInteger(e.end)||e.end<e.year||e.end===0||e.end>10000))throw Error('Ungültiger Zeitraum.');out.own.push({id:e.id,year:e.year,end:e.end??null,lane:e.lane,own:true,...Object.fromEntries(['title','date','question','text','perspective','source','uncertainty'].map(k=>[k,text(e[k])]))})}for(const [k,v] of Object.entries(record(x.notes)?x.notes:{})){if(key(k))out.notes[k]=text(v)}for(const [k,arr] of Object.entries(record(x.materials)?x.materials:{})){if(!key(k)||!Array.isArray(arr)||arr.length>100)throw Error('Ungültige Materialliste.');out.materials[k]=arr.map(m=>{if(!validMime(m.type)||typeof m.data!=='string'||m.data.length>12*1024*1024||!m.data.startsWith('data:'+m.type+';base64,')||!/^[A-Za-z0-9+/=]*$/.test(m.data.split(',')[1]))throw Error('Ungültige Materialdatei.');return {type:m.type,data:m.data,name:text(m.name,200),description:text(m.description)}})}if(Array.isArray(x.bounds)&&x.bounds.length===4&&x.bounds.every((n,i)=>Number.isInteger(n)&&n>0&&n<2050&&(!i||n>x.bounds[i-1])))out.bounds=x.bounds;out.boundaryReason=text(x.boundaryReason);out.boundaryHistory=Array.isArray(x.boundaryHistory)?x.boundaryHistory.filter(h=>Array.isArray(h.bounds)&&h.bounds.length===4&&h.bounds.every(Number.isFinite)).slice(-100).map(h=>({bounds:h.bounds,reason:text(h.reason)})):[];if(record(x.lensAssignments))for(const [mode,entries] of Object.entries(x.lensAssignments)){if(!Object.hasOwn(GLOBAL_LENSES,mode)||!record(entries))continue;out.lensAssignments[mode]={};for(const [id,slot] of Object.entries(entries))if(seen.has(id)&&GLOBAL_LENSES[mode].slots.some(s=>s[0]===slot))out.lensAssignments[mode][id]=slot;}out.relations=Array.isArray(x.relations)?x.relations.filter(r=>key(r.id)&&seen.has(r.a)&&seen.has(r.b)).slice(0,3000).map(r=>({id:r.id,a:r.a,b:r.b,type:text(r.type,100),claim:text(r.claim),evidence:text(r.evidence),counter:text(r.counter)})):[];validateReadings(x,out,seen);return out}
async function importFile(file){const rollback=JSON.parse(JSON.stringify(state));try{if(!file||file.size>70*1024*1024)throw Error('Bitte eine Sicherungsdatei bis 70 MB wählen.');const incoming=validate(JSON.parse(await file.text()));captureReadings();const previous=JSON.parse(JSON.stringify(state));const fresh=!state.own.length&&!Object.values(state.notes).some(v=>v.trim())&&!state.relations.length&&!state.boundaryReason;const ids=new Map();let added=0,conflicts=0;for(const e of incoming.own){const existing=state.own.find(x=>x.id===e.id);if(!existing){state.own.push(e);added++}else if(JSON.stringify(existing)!==JSON.stringify(e)){const id=uid();ids.set(e.id,id);state.own.push({...e,id,title:e.title+' (importierte Fassung)'});added++;conflicts++}}const map=id=>ids.get(id)||id;for(const [id,n] of Object.entries(incoming.notes)){const lk=parseLensNote(id);const k=lk?lensNoteKey(lk.mode,map(lk.id)):map(id);if(state.notes[k]&&state.notes[k]!==n){state.notes[k]+='\n\n— Importierte Notiz —\n'+n;conflicts++}else state.notes[k]=n}for(const [id,materials] of Object.entries(incoming.materials)){const k=map(id);state.materials[k]??=[];for(const m of materials)if(!state.materials[k].some(a=>a.data===m.data&&a.name===m.name))state.materials[k].push(m)}for(const r of incoming.relations){const next={...r,a:map(r.a),b:map(r.b)};const existing=state.relations.find(x=>x.id===r.id);if(!existing)state.relations.push(next);else if(JSON.stringify(existing)!==JSON.stringify(next))state.relations.push({...next,id:uid()})}for(const [mode,entries] of Object.entries(incoming.lensAssignments||{})){state.lensAssignments[mode]??={};for(const [id,slot] of Object.entries(entries)){const k=map(id),old=state.lensAssignments[mode][k];if(!old)state.lensAssignments[mode][k]=slot;else if(old!==slot){const nk=lensNoteKey(mode,k);state.notes[nk]=(state.notes[nk]||'')+'\nImportierte abweichende Zuordnung: '+GLOBAL_LENSES[mode].slots.find(s=>s[0]===slot)[1];conflicts++;}}}mergeReadings(incoming,map,fresh,previous);if(fresh){state.bounds=incoming.bounds;state.boundaryReason=incoming.boundaryReason;state.boundaryHistory=incoming.boundaryHistory}else if(incoming.boundaryReason&&incoming.boundaryReason!==state.boundaryReason)state.boundaryHistory.push({bounds:incoming.bounds,reason:'Importierter Entwurf: '+incoming.boundaryReason});await save();render();toast(`${added} Spuren ergänzt; ${conflicts} abweichende Fassungen erhalten.`)}catch(e){state=rollback;toast('Import fehlgeschlagen: '+e.message)}finally{$('#restoreFile').value=''}}
function mediaBadge(e){const media=HISTORICAL_MEDIA[e.id];return media?`<span class="media-badge">${media.some(m=>m.kind!=='audio')?'▶ Film':'◖ Ton'}${media.some(m=>m.kind==='audio')&&media.some(m=>m.kind!=='audio')?' & Ton':''}</span>`:''}
