function openMemoria(){
 show(`<p class="metadata">MEMORIA-THEORIEN · EIN ZUGANG ZUM GESAMTEN BESTAND</p><h2 id="dialogTitle">Wer erinnert sich – und in welcher Gesellschaft?</h2><p class="lead">Das vergangene Geschehen, eine Erinnerung daran und eine historische Untersuchung sind nicht dasselbe.</p><div class="memoria-intro-grid"><article><p class="eyebrow">MAURICE HALBWACHS</p><h3>Erinnern hat soziale Rahmen.</h3><p>Menschen erinnern selbst, aber nicht unabhängig von anderen. Gespräche, Gruppenzugehörigkeiten, Sprache und vertraute Orte geben dem Vergangenen Bedeutung. Eine Familie, eine politische Bewegung und eine Schulklasse können dasselbe Geschehen unterschiedlich erinnern. «Kollektiv» bezeichnet dabei kein gemeinsames Gehirn und keine überall gleiche Erinnerung.</p><p><strong>Deine Frage:</strong> Wer erzählt wem etwas – und welche Sicht wird in dieser Gruppe selbstverständlich?</p><button data-open="halbwachs">Halbwachs und sein Untersuchungsauftrag ↗</button></article><article><p class="eyebrow">JAN ASSMANN</p><h3>Wie überdauert Erinnerung die Beteiligten?</h3><p>Kommunikatives Gedächtnis lebt vom alltäglichen Austausch und Erfahrungen lebender Generationen. Kulturelles Gedächtnis wird durch besondere Formen, Medien und Praktiken gestützt: etwa Texte, Rituale oder Erinnerungsorte. Ein Gegenstand erinnert nicht von selbst; Menschen deuten, pflegen und verwenden ihn.</p><p><strong>Deine Frage:</strong> Was verändert sich, wenn eine erzählte Erfahrung zur Gedenkfeier, Inschrift oder Unterrichtsdarstellung wird?</p><button data-open="assmann">Assmann und sein Untersuchungsauftrag ↗</button></article></div><section class="memory-transfer"><h3>Ein Ereignis – mehrere Gegenwarten</h3><p>Wähle eine beliebige Spur. Lege gedanklich drei Ebenen auseinander: das damalige Geschehen, eine spätere Erinnerung und deine heutige Untersuchung. Dieselbe Fotografie kann Beleg eines Ereignisses und Bestandteil einer späteren Erinnerungskultur sein.</p><div class="memory-questions"><p><strong>Träger*innen</strong><br>Wer erinnert? Welche Gruppe spricht, welche widerspricht?</p><p><strong>Vermittlung</strong><br>Gespräch, Jahrestag, Denkmal, Schulbuch oder digitaler Feed?</p><p><strong>Auswahl</strong><br>Was wird betont? Welche Auslassung kannst du mit einer weiteren Quelle belegen?</p></div><p>Die Grafik ist keine Stufenfolge vom «einfachen» Gespräch zum «höheren» kulturellen Gedächtnis. Formen können sich überschneiden. Auch ein digitales Archiv garantiert noch keine lebendige Erinnerung.</p><button id="enterMemoria" class="primary">Die gewählte Spur in Erinnerungsräumen untersuchen →</button></section><details><summary>Theoretische Grundlagen</summary><p>Didaktische Paraphrasen: Halbwachs, <em>La mémoire collective</em> (1950); Jan Assmann, <em>Kollektives Gedächtnis und kulturelle Identität</em> (1988). Ergänzend Assmanns Überlegungen zu digitaler Speicherung und erinnernder Praxis.</p><ul class="source-list">${sourceHtml(['halbwachs','assmann','assmannDigital'])}</ul></details>`,'MEMORIA · ERINNERUNG UNTERSUCHEN');
 $('#enterMemoria').onclick=()=>{popup.close();switchRepresentation('memoria')};
}

function initCategoryControls(){
 const choices=$('#categoryChoices');
 choices.innerHTML=LANES.map(([id,label,,color])=>`<div class="category-chip" style="--category-color:${color}"><label class="category-choice"><input type="checkbox" data-category="${id}" checked><span>${esc(label)}</span></label><button type="button" data-isolate="${id}" aria-label="Nur ${esc(label)} anzeigen" title="Nur diese Kategorie anzeigen">Solo</button></div>`).join('');
 const update=()=>{
  $$('[data-category]').forEach(input=>{input.checked=visibleCategories.has(input.dataset.category)});
  $('#categoryStatus').textContent=visibleCategories.size?`${visibleCategories.size} von ${LANES.length} Kategorien sichtbar`:'Keine Kategorie ausgewählt – schalte eine Kategorie ein.';
  render();
  if(representation==='timeline')$('#scroll').scrollTop=0;
 };
 choices.onclick=e=>{const solo=e.target.closest('[data-isolate]');if(!solo)return;visibleCategories=new Set([solo.dataset.isolate]);update()};
 choices.onchange=e=>{const id=e.target.dataset.category;if(!LANES.some(l=>l[0]===id))return;if(e.target.checked)visibleCategories.add(id);else visibleCategories.delete(id);update()};
 $('#categoriesAll').onclick=()=>{visibleCategories=new Set(LANES.map(l=>l[0]));update()};
 $('#categoriesNone').onclick=()=>{visibleCategories.clear();update()};
 $('#categoryStatus').textContent=`${LANES.length} von ${LANES.length} Kategorien sichtbar`;
}
